import numpy as np, scipy.sparse as sp
from scipy.sparse.csgraph import dijkstra
sk=np.load('/tmp/skeleton.npy').astype(bool); ys,xs=np.where(sk); ij={(y,x):i for i,(y,x) in enumerate(zip(ys,xs))}
rows=[];cols=[];ds=[]
for i,(y,x) in enumerate(zip(ys,xs)):
 for dy in [-1,0,1]:
  for dx in [-1,0,1]:
   if not(dx or dy):continue
   j=ij.get((y+dy,x+dx))
   if j is not None:
    if dx and dy and (ij.get((y,x+dx)) is not None or ij.get((y+dy,x)) is not None):continue
    rows.append(i);cols.append(j);ds.append(np.hypot(dx,dy))
g=sp.csr_matrix((ds,(rows,cols)),shape=(len(xs),len(xs)))
deg=np.diff(g.indptr); ends=np.where(deg==1)[0]; coords=[(xs[i],ys[i]) for i in ends]
D=dijkstra(g,indices=ends)
print(coords)
for ii,c in enumerate(coords):
 print(c,[(coords[jj],round(D[ii,ends[jj]])) for jj in np.argsort(D[ii]) if jj!=ii and np.isfinite(D[ii,ends[jj]])][:7])
