import numpy as np, scipy.sparse as sp
from scipy.sparse.csgraph import dijkstra
from PIL import Image,ImageDraw
sk=np.load('/tmp/skeleton.npy').astype(bool); ys,xs=np.where(sk); ij={(y,x):i for i,(y,x) in enumerate(zip(ys,xs))}
rows=[];cols=[];ds=[]
for i,(y,x) in enumerate(zip(ys,xs)):
 for dy in [-1,0,1]:
  for dx in [-1,0,1]:
   if not(dx or dy):continue
   j=ij.get((y+dy,x+dx))
   if j is not None:
    if dx and dy and (ij.get((y,x+dx)) is not None or ij.get((y+dy,x)) is not None):continue
    rows.append(i);cols.append(j);ds.append(np.hypot(dx,dy))
g=sp.csr_matrix((ds,(rows,cols)),shape=(len(xs),len(xs)))
def path(a,b):
 d,pre=dijkstra(g,indices=ij[a],return_predecessors=True); p=[];i=ij[b]
 while i!=-9999:p.append(i); i=pre[i]
 return list(zip(xs[p[::-1]],ys[p[::-1]]))
paths=[path((531,361),(533,652)),path((508,398),(552,368)),path((509,594),(553,563))]
print([len(p) for p in paths])
im=Image.open('/app/target.png').convert('RGB');dr=ImageDraw.Draw(im)
for p,c in zip(paths,[(255,0,0),(0,80,255),(0,200,40)]):
 for a,b in zip(p,p[1:]):dr.line((*a,*b),fill=c,width=1)
im.crop((350,500,660,565)).resize((1240,260)).save('/tmp/allpath.png')
